@Component
public class TraceLifecycle implements BeanPostProcessor {

    @Override
    public Object postProcessBeforeInitialization(Object bean, String name) {
        if (name.startsWith("order")) log.info("[후처리 앞] {}", name);
        return bean;
    }

    @Override
    public Object postProcessAfterInitialization(Object bean, String name) {
        if (name.startsWith("order")) log.info("[후처리 뒤] {}", name);
        return bean;
    }
}

@Service
public class OrderServiceV3 {
